import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Card, Form, Button, Input, DatePicker, Spin } from 'antd'
import demoActions from '../../redux/demo/actions'
import validator from '../../../helpers/validator'
import moment from 'moment'

const FormItem = Form.Item
const { createJDPolicy } = demoActions

class ClaimDemo extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      submitting: false,
      getCreateJDStatus: ''
    }
  }

  componentWillReceiveProps (nextProps) {
    const { formStatus } = nextProps
    if (formStatus === 'reset') {
      this.setState({ submitting: false })
      this.props.form.resetFields()
      this.props.triggerFormStatus()
    }
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    this.setState({ submitting: true })
    const valid = await this.validateForm()
    if (!valid) {
      this.setState({ submitting: false })
      return
    }
    const { form } = this.props
    const data = form.getFieldsValue()
    const payload = {
      name: data.name,
      email: data.email,
      handphone_no: data.phone,
      city: data.city,
      flight_code: data.flight_code,
      airport_code: data.airport_code,
      departure_date: moment(data.departure_date).format('YYYY-MM-DD HH:mm:ss')
    }
    this.props.createJDPolicy({ payload })
  }

  render () {
    const { submitting } = this.state
    const { form, loaderStop } = this.props
    const { getFieldDecorator } = form
    let finalLoader = submitting
    if (loaderStop) {
      finalLoader = false
    }
    return (
      <div>
        <Spin spinning={finalLoader}>
          <Card>
            <Form onSubmit={this.onSubmit}>
              <Row>
                <Col lg={12} sm={24} style={{ padding: '20px' }}>
                  <label className='custom-label'>Name</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: John Doe'>
                    {getFieldDecorator('name', {
                      rules: [
                        { required: true, message: 'Name can not be empty' },
                        { validator: validator.validateName }
                      ]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <label className='custom-label'>Email</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: johndoe@gmail.com'>
                    {getFieldDecorator('email', {
                      rules: [{
                        type: 'email', message: 'The input is not valid E-mail!'
                      }, {
                        required: true, message: 'Please input your E-mail!'
                      }]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <label className='custom-label'>Handphone no</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: 08800165656'>
                    {getFieldDecorator('phone', {
                      rules: [
                        { required: true, message: 'Handphone can not be empty' },
                        { validator: validator.checkPhone }
                      ]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <label className='custom-label'>City</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: Jakarta'>
                    {getFieldDecorator('city', {
                      rules: [
                        { required: true, message: 'City can not be empty' },
                        { validator: validator.validateName }
                      ]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                </Col>
                <Col lg={12} sm={24} style={{ padding: '20px' }}>
                  <label className='custom-label'>Flight code</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: JT-280'>
                    {getFieldDecorator('flight_code', {
                      rules: [
                        { required: true, message: 'Flight code can not be empty' }
                      ]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <label className='custom-label'>Airport code</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: CGK'>
                    {getFieldDecorator('airport_code', {
                      rules: [
                        { required: true, message: 'Airport code can not be empty' }
                      ]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <label className='custom-label'>Departure date</label>
                  <FormItem style={{ fontSize: '11px' }}>
                    {getFieldDecorator('departure_date', {
                      rules: [
                        { required: true, message: 'Departure date can not be empty' }
                      ]
                    })(
                      <DatePicker
                        showTime
                        format='YYYY-MM-DD HH:mm'
                        onChange={this.onChange}
                        onOk={this.onOk}
                        placeholder={'YYYY-MM-DD HH:mm'}
                      />
                    )}
                  </FormItem>
                </Col>
              </Row>
              <Row>
                <Col>
                  <div style={{ textAlign: 'center' }}>
                    <Button
                      key='submit'
                      type='primary'
                      htmlType='submit'
                      style={{ marginLeft: '10px' }}
                    >
                                            Submit
                    </Button>
                  </div>
                </Col>
              </Row>
            </Form>
          </Card>
        </Spin>
      </div>
    )
  }
}

const WrappedForm = Form.create({})(ClaimDemo)

export default connect(
  state => ({
    demo: state.Demo
  }),
  { createJDPolicy }
)(WrappedForm)
