import React from 'react'
import { connect } from 'react-redux'
import { Tabs, Alert } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import CreateJDPolicy from './CreateJDPolicy'
import OAGSimulate from './OAGSimulate'
import PermissionChecker from '../../../components/permissionChecker'

const TabPane = Tabs.TabPane

class ClaimDemo extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      getCreateJDStatus: '',
      getCreateOAGStatus: '',
      loaderStop: false,
      formStatus: ''
    }
  }

  componentWillReceiveProps (nextProps) {
    const { getCreateJDStatus, getCreateOAGStatus } = nextProps.demo
    if ((getCreateJDStatus !== '') || (getCreateOAGStatus !== '')) {
      this.setState({
        getCreateJDStatus,
        getCreateOAGStatus,
        loaderStop: true
      })
    }
    if ((getCreateJDStatus !== '' && getCreateJDStatus === 'success') || (getCreateOAGStatus !== '' && getCreateOAGStatus === 'success')) {
      this.setState({
        loaderStop: true,
        formStatus: 'reset'
      })
    }
  }
  onClearMessageJDStatus = () => {
    this.setState({ getCreateJDStatus: '' })
  }
  onClearMessageOAGStatus = () => {
    this.setState({ getCreateOAGStatus: '' })
  }
  onTriggerFormStatus = () => {
    this.setState({
      formStatus: '',
      loaderStop: false
    })
  }
  onResetLoader = () => {
    this.setState({ loaderStop: false })
  }
  render () {
    const {
      getCreateJDStatus,
      loaderStop,
      formStatus,
      getCreateOAGStatus
    } = this.state
    const { permissions } = this.props
    return (
      <LayoutContentWrapper className='referral-table' style={{ color: '#788195' }}>
        <LayoutContent>
          <h1>Create Demo Travel Policies.</h1>
          <Tabs defaultActiveKey='1'>
            <TabPane tab='Create JD policy' key='1'>
              <PermissionChecker permissionSetter='ops.demo_create_jd_policy' permissionGetter={permissions} >

                {
                  (getCreateJDStatus !== '' && getCreateJDStatus !== 'success') && (
                    <Alert
                      style={{ marginBottom: '10px', marginTop: '20px' }}
                      message=''
                      description={getCreateJDStatus}
                      type='error'
                      showIcon
                      closeText='Close'
                      onClose={this.onClearMessageJDStatus}
                    />
                  )
                }
                {
                  (getCreateJDStatus !== '' && getCreateJDStatus === 'success') && (
                    <Alert
                      style={{ marginBottom: '10px', marginTop: '20px' }}
                      message=''
                      description={`Policy is ${getCreateJDStatus} created`}
                      type='success'
                      showIcon
                      closeText='Close'
                      onClose={this.onClearMessageJDStatus}
                    />
                  )
                }

                <CreateJDPolicy
                  formStatus={formStatus}
                  loaderStop={loaderStop}
                  triggerFormStatus={this.onTriggerFormStatus}
                  onResetLoader={this.onResetLoader}
                />
              </PermissionChecker>
            </TabPane>

            <TabPane tab='Simulate OAG notification' key='2'>
              <PermissionChecker permissionSetter='ops.demo_simulate_oag_notifictaion' permissionGetter={permissions} >
                {
                  (getCreateOAGStatus !== '' && getCreateOAGStatus !== 'success') && (
                    <div>
                      <Alert
                        style={{ marginBottom: '10px', marginTop: '20px' }}
                        message=''
                        description={getCreateOAGStatus}
                        type='error'
                        showIcon
                        closeText='Close'
                        onClose={this.onClearMessageOAGStatus}
                      />
                    </div>
                  )
                }
                {
                  (getCreateOAGStatus !== '' && getCreateOAGStatus === 'success') && (
                    <div>
                      <Alert
                        style={{ marginBottom: '10px', marginTop: '20px' }}
                        message=''
                        description={`Policy is ${getCreateOAGStatus} created`}
                        type='success'
                        showIcon
                        closeText='Close'
                        onClose={this.onClearMessageOAGStatus}
                      />
                    </div>
                  )
                }
                <OAGSimulate
                  formStatus={formStatus}
                  loaderStop={loaderStop}
                  triggerFormStatus={this.onTriggerFormStatus}
                  onResetLoader={this.onResetLoader}
                />
              </PermissionChecker>
            </TabPane>
          </Tabs>
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

export default connect(
  state => ({
    demo: state.Demo
  }),
  { }
)(ClaimDemo)
