import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Card, Form, Button, Input, DatePicker, Spin } from 'antd'
import demoActions from '../../redux/demo/actions'
import moment from 'moment'

const FormItem = Form.Item
const { createOAGNotif } = demoActions

class ClaimDemo extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      submitting: false,
      getCreateOAGStatus: ''
    }
  }

  componentWillReceiveProps (nextProps) {
    const { formStatus } = nextProps
    if (formStatus === 'reset') {
      this.setState({ submitting: false })
      this.props.form.resetFields()
      this.props.triggerFormStatus()
    }
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    this.setState({ submitting: true })
    const valid = await this.validateForm()
    if (!valid) {
      this.setState({ submitting: false })
      return
    }
    this.props.onResetLoader()
    const { form } = this.props
    const data = form.getFieldsValue()
    const payload = {
      airline_code: data.airline_code,
      arrival_airport_code: data.arrival_airport_code,
      departure_airport_code: data.departure_airport_code,
      flight_number: data.flight_number,
      latest_departure: moment(data.latest_departure).format('YYYY-MM-DDTHH:mm:00'),
      sched_departure_local: moment(data.sched_departure_local).format('YYYY-MM-DDTHH:mm:00')
    }
    this.props.createOAGNotif(payload)
  }

  render () {
    const { submitting } = this.state
    const { form, loaderStop } = this.props
    const { getFieldDecorator } = form
    let finalLoader = submitting
    if (loaderStop) {
      finalLoader = false
    }
    return (
      <div>
        <Spin spinning={finalLoader}>
          <Card>
            <Row>
              <Col>
                <Form onSubmit={this.onSubmit}>
                  <label className='custom-label'>Latest departure date</label>
                  <FormItem style={{ fontSize: '11px' }}>
                    {getFieldDecorator('latest_departure', {
                      rules: [
                        { required: true, message: 'Latest departure date can not be empty' }
                      ]
                    })(
                      <DatePicker
                        showTime
                        format='YYYY-MM-DD HH:mm'
                        onChange={this.onChange}
                        onOk={this.onOk}
                        placeholder={'YYYY-MM-DD HH:mm'}
                      />
                    )}
                  </FormItem>
                  <label className='custom-label'>Arrival airport code</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: DPS'>
                    {getFieldDecorator('arrival_airport_code', {
                      rules: [
                        { required: true, message: 'Arrival airport code can not be empty' }
                      ]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <label className='custom-label'>Flight number</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: 201'>
                    {getFieldDecorator('flight_number', {
                      rules: [{
                        required: true, message: 'Flight Number can not be empty'
                      }]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <label className='custom-label'>Sched departure local date</label>
                  <FormItem style={{ fontSize: '11px' }}>
                    {getFieldDecorator('sched_departure_local', {
                      rules: [
                        { required: true, message: 'Sched departure local date can not be empty' }
                      ]
                    })(
                      <DatePicker
                        showTime
                        format='YYYY-MM-DD HH:mm'
                        onChange={this.onChange}
                        onOk={this.onOk}
                        placeholder={'YYYY-MM-DD HH:mm'}
                      />
                    )}
                  </FormItem>
                  <label className='custom-label'>Departure airport code</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: CGK'>
                    {getFieldDecorator('departure_airport_code', {
                      rules: [
                        { required: true, message: 'Departure Airport Code can not be empty' }
                      ]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <label className='custom-label'>Airline code</label>
                  <FormItem style={{ fontSize: '11px' }} extra='eg: JT'>
                    {getFieldDecorator('airline_code', {
                      rules: [
                        { required: true, message: 'Airline Code can not be empty' }
                      ]
                    })(
                      <Input size='default' className='input-box' />
                    )}
                  </FormItem>
                  <div style={{ textAlign: 'right' }}>
                    <Button
                      key='submit'
                      type='primary'
                      htmlType='submit'
                      style={{ marginLeft: '10px' }}
                    >
                                            Submit
                    </Button>
                  </div>
                </Form>
              </Col>
            </Row>
          </Card>
        </Spin>
      </div>
    )
  }
}

const WrappedForm = Form.create({})(ClaimDemo)

export default connect(
  state => ({
    demo: state.Demo
  }),
  { createOAGNotif }
)(WrappedForm)
